import {points} from './engine.mjs';
import {newBlackjack,blackjackAct,blackjackTick,blackjackView} from './blackjack.mjs';
import {RoomGame} from './room-game.mjs';
export class SoloBlackjack{
 constructor(host,{bank,role,skillsOn=false,onBank,onExit,toast,beep,reduced}){Object.assign(this,{bank,role,skillsOn,onBank,onExit,toast});this.round=0;this.alive=true;this.rooms={send:d=>this.send(d),exit:()=>this.exit()};this.view=new RoomGame(host,{rooms:this.rooms,toast,beep,reduced});this.start();this.timer=setInterval(()=>{if(this.alive&&blackjackTick(this.game,[false],Date.now()))this.emit()},200)}
 start(){if(this.bank<1){this.toast('筹码不足，请回大厅领取练习筹码');return}this.round++;this.endedAt=0;this.used=false;this.bounty=false;this.rewardDone=false;this.startBank=this.bank;this.game=newBlackjack([this.bank]);this.emit()}
 emit(){if(this.game.done&&!this.rewardDone){this.rewardDone=true;const p=this.game.players[0];let reward=0;if(this.skillsOn&&this.role===2&&p.bank<this.startBank)reward=Math.min(100,Math.floor((this.startBank-p.bank)/2));if(this.bounty&&p.hands.some(h=>h.delta>0&&points(h.cards)===21))reward+=150;p.bank+=reward;if(reward){p.result+=' · 技能奖励 '+reward;p.delta+=reward;this.view.scene?.skillEffect(this.role,0)}p.delta=p.bank-this.startBank}this.bank=this.game.players[0].bank;this.onBank(this.bank);if(this.game.done&&!this.endedAt)this.endedAt=Date.now();const r={solo:true,skill:{enabled:this.skillsOn,role:this.role,used:this.used},mode:'blackjack',round:this.round,status:this.game.done?'roundEnd':'playing',you:0,host:true,serverNow:Date.now(),endedAt:this.endedAt,reviewUntil:this.endedAt+1800,seats:[{id:'you',name:'你',role:this.role,seed:[12501,24403,33807,45709][this.role],bank:this.bank,ready:false,bot:false}],game:blackjackView(this.game)};if(this.game.peek){r.game.dealer=this.game.dealer.map(c=>({...c}));r.game.dealerPoints=points(this.game.dealer);r.game.reveal=true}this.view.apply(r)}
 async send(data){try{if(data.kind==='next'){if(Date.now()<this.endedAt+1800)return;this.start()}else if(data.action==='skill'){this.skill(data.index)}else{blackjackAct(this.game,0,data.action,Number(data.amount));this.emit()}}catch(e){this.toast(e.message)}}
 skill(index){const g=this.game,p=g.players[0],h=p.hands[p.active];if(!this.skillsOn||this.used||g.phase!=='players'||g.turn!==0||this.role===2)return;if(this.role===0)g.peek=true;if(this.role===1){if(p.bank<20||!Number.isInteger(index)||!h.cards[index])throw Error('请选择手牌并保留 20 筹码');p.bank-=20;h.cards[index]=g.deck.pop();h.modified=true;if(points(h.cards)>=21)blackjackAct(g,0,'stand')}if(this.role===3){if(p.bank<30)throw Error('需要 30 筹码');p.bank-=30;this.bounty=true}this.used=true;this.view.scene?.skillEffect(this.role,0);this.emit()}
 exit(){if(!this.game.done&&this.game.players[0].bet&&!confirm('离桌将放弃本局已下注筹码。确定离开？'))return;this.destroy();this.onExit()}
 destroy(){this.alive=false;clearInterval(this.timer);this.view.destroy()}
}
